descriptor.templateCss:
.guardas-grid-container {
    background-color: #ffffff;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    font-family: 'Roboto', sans-serif;
    color: #333;
}

.grid-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 16px;
    background-color: #f5f7fa;
    border-bottom: 2px solid #cfd8dc;
    flex-wrap: wrap;
    gap: 10px;
}

.guard-info {
    display: flex;
    align-items: center;
    gap: 10px;
}

.guard-icon { font-size: 22px; }

.guard-info-text {
    display: flex;
    flex-direction: column;
}

#guard-name {
    font-size: 15px;
    font-weight: 700;
    color: #263238;
}

.guard-mode-badge {
    font-size: 11px;
    font-weight: 600;
    color: #607d8b;
}

.date-picker-container {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    font-weight: 500;
    color: #455a64;
}

.form-control-date {
    padding: 6px 10px;
    font-size: 14px;
    border: 1px solid #cfd8dc;
    border-radius: 4px;
    outline: none;
    color: #455a64;
    cursor: pointer;
    font-family: inherit;
    background-color: #ffffff;
}

.form-control-date:focus { border-color: #607d8b; }

.help-banner {
    padding: 6px 16px;
    background-color: #fff8e1;
    color: #8d6e00;
    font-size: 12px;
    border-bottom: 1px solid #ffecb3;
}

.table-wrapper {
    flex-grow: 1;
    overflow: auto;
}

table {
    border-collapse: collapse;
    width: 100%;
    min-width: max-content;
    margin-bottom: 40px;
}

th, td {
    box-sizing: border-box;
    border: 1px solid #cfd8dc;
    padding: 2px;
    text-align: center;
    font-size: 12px;
    min-width: 38px;
    height: 28px;
}

.col-fixed-1 { position: sticky; left: 0; width: 65px; min-width: 65px; background-color: #eceff1; font-weight: bold; z-index: 20; }
.col-fixed-2 { position: sticky; left: 65px; width: 160px; min-width: 160px; background-color: #eceff1; font-weight: bold; text-align: left; padding-left: 8px; z-index: 20; border-right: 2px solid #90a4ae; }

th {
    background-color: #eceff1;
    color: #37474f;
    font-weight: bold;
    position: sticky;
    top: 0;
    z-index: 10;
}

th.col-fixed-1, th.col-fixed-2 { z-index: 30; }

#filtro-grupo {
    width: 100%;
    box-sizing: border-box;
    margin-top: 4px;
    font-size: 11px;
    padding: 3px 4px;
    border: 1px solid #90a4ae;
    border-radius: 3px;
    outline: none;
    font-family: inherit;
    font-weight: normal;
}

.day-input {
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    border: none;
    background: transparent;
    text-align: center;
    font-family: inherit;
    font-size: 12px;
    padding: 4px 2px;
    outline: none;
    transition: background-color 0.4s ease;
}

.day-input:focus {
    background-color: #e3f2fd;
    box-shadow: inset 0 0 0 2px #1976d2;
}

.day-input-numero { color: #1976d2; font-weight: 600; }
.day-input-texto { color: #6a1b9a; font-weight: 500; }

.sum-col, .total-col {
    background-color: #f1f8e9;
    font-weight: bold;
    vertical-align: middle;
}

.guard-error {
    text-align: center;
    padding: 24px;
    font-weight: bold;
    color: #d32f2f;
}

