                        groupAssets = grupos;
                        setSelectorToCurrentMonth();
                        renderGrid();
                    });
                });
            });
        });
    }

    function obtenerUsuarioActual(cb) {
        $ctx.http.get('/api/auth/user').subscribe(function(u) { cb(u); }, function() { cb(null); });
    }

    // Relación Guarda (ASSET, origen) -> Usuario (destino). Buscamos por el lado
    // "to" del usuario y filtramos el origen que sea un ASSET.
    function buscarGuardaDeUsuario(userId, cb) {
        const url = '/api/relations?toId=' + userId + '&toType=USER&relationTypeGroup=COMMON';
        $ctx.http.get(url).subscribe(function(rels) {
            const candidatos = (rels || []).filter(r =>
                r.from && r.from.entityType === 'ASSET' &&
                (!REL_GUARD_TO_USER || r.type === REL_GUARD_TO_USER)
            );
            if (candidatos.length === 0) { cb(null); return; }
            const assetId = candidatos[0].from.id;
            $ctx.http.get('/api/asset/' + assetId).subscribe(function(asset) { cb(asset); }, function() { cb(null); });
        }, function() { cb(null); });
    }

    function obtenerModoEntrada(guardId, cb) {
        $ctx.http.get('/api/plugins/telemetry/ASSET/' + guardId + '/values/attributes').subscribe(function(attrs) {
            const found = (attrs || []).find(a => (a.key || '').toLowerCase() === MODE_ATTRIBUTE.toLowerCase());
            cb(found && String(found.value).toLowerCase() === MODE_TEXT_VALUE.toLowerCase() ? 'texto' : 'numero');
        }, function() { cb('numero'); });
    }

    // Relación Guarda (ASSET, origen) -> Grupo de riego (ASSET, destino)
    function obtenerGruposDeGuarda(guardId, cb) {
        const url = '/api/relations?fromId=' + guardId + '&fromType=ASSET&relationTypeGroup=COMMON';
        $ctx.http.get(url).subscribe(function(rels) {
            const targetIds = (rels || [])
                .filter(r => r.to && r.to.entityType === 'ASSET' && (!REL_GUARD_TO_GROUP || r.type === REL_GUARD_TO_GROUP))
                .map(r => r.to.id);
            if (targetIds.length === 0) { cb([]); return; }
            cargarAssetsPorId(targetIds, cb);
        }, function() { cb([]); });
    }

    function cargarAssetsPorId(ids, cb) {
        const url = '/api/assets?assetIds=' + ids.join(',');
        $ctx.http.get(url).subscribe(function(assets) { cb(assets || []); }, function() { cb([]); });
    }

    // ============================================================
    // RENDER DE LA REJILLA
    // ============================================================
    function renderGrid() {
        if (!guardAsset) return;

        $container.find('#days-header-row').empty();
        $container.find('#assets-body').empty().append(
            '<tr><td colspan="40" style="text-align:center;padding:20px;font-weight:bold;">Cargando datos...</td></tr>'
        );

        if (groupAssets.length === 0) {
            mostrarError('No tienes ningún grupo de riego asignado todavía. Contacta con el administrador.');
            return;
        }

        const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
        const startTs = new Date(currentYear, currentMonth, 1).getTime();
        const endTs = new Date(currentYear, currentMonth + 1, 0, 23, 59, 59, 999).getTime() + 86400000;

        cargarAtributosGrupos(groupAssets, function(assetsConAtributos) {
            assetsConAtributos.sort((a, b) => {
                const ia = ORDEN_GRUPOS_EXCEL.indexOf(a.name);
                const ib = ORDEN_GRUPOS_EXCEL.indexOf(b.name);
                const posA = ia === -1 ? Number.MAX_SAFE_INTEGER : ia;
                const posB = ib === -1 ? Number.MAX_SAFE_INTEGER : ib;
                if (posA !== posB) return posA - posB;
                return a.name.localeCompare(b.name, 'es');
            });
            buildEditableTable(daysInMonth, assetsConAtributos);
            cargarValoresExistentes(assetsConAtributos, startTs, endTs);
        });
    }

    function cargarAtributosGrupos(assets, callback) {
        assets.forEach(a => { a.sector = 999999; });
        let idx = 0;
        const BATCH_SIZE = 5;
        function next() {
            if (idx >= assets.length) { callback(assets); return; }
            const batch = assets.slice(idx, idx + BATCH_SIZE);
            idx += BATCH_SIZE;
            let completed = 0;
            batch.forEach(asset => {
                $ctx.http.get('/api/plugins/telemetry/ASSET/' + asset.id.id + '/values/attributes').subscribe(function(data) {
                    (data || []).forEach(attr => {
                        if ((attr.key || '').toLowerCase() === 'sector') asset.sector = parseFloat(attr.value) || attr.value;
                    });
                    if (++completed === batch.length) next();
                }, function() { if (++completed === batch.length) next(); });
            });
        }
        next();
    }

    function buildEditableTable(days, assets) {
        const $headerRow = $container.find('#days-header-row').empty();
        const $body = $container.find('#assets-body').empty();

        $headerRow.append('<th class="col-fixed-1">SECTOR</th>');
        $headerRow.append('<th class="col-fixed-2">GRUPO<br><input type="text" id="filtro-grupo" class="filter-input" placeholder="Filtrar..."></th>');
        for (let i = 1; i <= days; i++) $headerRow.append('<th>' + i + '</th>');
        if (modoEntrada === 'numero' && SHOW_TOTAL_COLUMN) {
            $headerRow.append('<th style="background-color:#eceff1;">TOTAL<br><span style="font-weight:normal;font-size:10px;">(L/s)</span></th>');
        }

        $container.find('#filtro-grupo').off('input').on('input', function() {
            const q = $(this).val().toLowerCase().trim();
            $body.find('tr').each(function() {
                const nombre = $(this).find('td.col-fixed-2').text().toLowerCase();
                $(this).toggle(nombre.includes(q));
            });
        });

        assets.forEach(asset => {
            const secDisplay = asset.sector === 999999 ? '-' : asset.sector;
            let rowHtml = '<tr id="row-' + asset.id.id + '">' +
                '<td class="col-fixed-1">' + secDisplay + '</td>' +
                '<td class="col-fixed-2">' + nombreConRemota(asset.name) + '</td>';

            for (let i = 1; i <= days; i++) {
                const inputModeAttr = modoEntrada === 'numero' ? 'inputmode="numeric"' : '';
                const inputClass = modoEntrada === 'texto' ? 'day-input-texto' : 'day-input-numero';
                rowHtml += '<td class="day-cell" data-day="' + i + '">' +
                    '<input type="text" ' + inputModeAttr + ' class="day-input ' + inputClass + '" ' +
                    'id="input-' + asset.id.id + '-' + i + '" data-asset-id="' + asset.id.id + '" data-day="' + i + '">' +
                    '</td>';
            }

            if (modoEntrada === 'numero' && SHOW_TOTAL_COLUMN) {
                rowHtml += '<td class="total-col sum-col">0</td>';
            }
            rowHtml += '</tr>';

            $body.append($(rowHtml));
        });

        attachInputHandlers();
    }

    function attachInputHandlers() {
        $container.find('.day-input').off('blur').on('blur', function() {
            guardarCelda($(this));
        });

        $container.find('.day-input').off('keydown').on('keydown', function(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                $(this).blur();
                moverSiguiente($(this));
            }
        });

        if (modoEntrada === 'numero') {
            $container.find('.day-input').off('input').on('input', function() {
                const v = $(this).val();
                const cleaned = v.replace(/[^0-9]/g, '');
                if (cleaned !== v) $(this).val(cleaned);
            });
        }
    }

    function moverSiguiente($input) {
        const $td = $input.closest('td');
        const $nextTd = $td.next('td.day-cell');
        if ($nextTd.length) $nextTd.find('.day-input').focus().select();
    }

    // ============================================================
    // GUARDADO
    // ============================================================
    function guardarCelda($input) {
        const assetId = $input.data('asset-id');
        const day = parseInt($input.data('day'));
        const valorNuevo = ($input.val() || '').trim();
        const valorAnterior = $input.data('valor-anterior') || '';

        if (valorNuevo === valorAnterior) return;

        const ts = new Date(currentYear, currentMonth, day, 12, 0, 0).getTime();
        const key = modoEntrada === 'texto' ? KEY_TEXT : KEY_NUMERIC;

        if (valorNuevo === '') {
            const urlDelete = '/api/plugins/telemetry/ASSET/' + assetId + '/timeseries/delete?keys=' + key + '&startTs=' + (ts - 1000) + '&endTs=' + (ts + 1000);
            $ctx.http.delete(urlDelete).subscribe(function() {
                $input.data('valor-anterior', '');
                flashInput($input, '#eceff1');
                if (modoEntrada === 'numero') recalcularTotalFila($input.closest('tr'));
            }, function() {
                alert('No se pudo borrar el valor.');
                $input.val(valorAnterior);
            });
            return;
        }

        if (modoEntrada === 'numero' && isNaN(valorNuevo)) {
            alert('Este grupo solo admite valores numéricos (caudal en L/s).');
            $input.val(valorAnterior);
            return;
        }

        const valorAGuardar = modoEntrada === 'numero' ? Number(valorNuevo) : valorNuevo;
        const payload = { ts: ts, values: {} };
        payload.values[key] = valorAGuardar;

        $input.css('background-color', '#fff9c4');
        $ctx.http.post('/api/plugins/telemetry/ASSET/' + assetId + '/timeseries/ANY', payload).subscribe(function() {
            $input.data('valor-anterior', valorNuevo);
            flashInput($input, '#c8e6c9');
            if (modoEntrada === 'numero') recalcularTotalFila($input.closest('tr'));
        }, function() {
            alert('Error al guardar el dato. Se restaura el valor anterior.');
            $input.val(valorAnterior);
            flashInput($input, '#ffcdd2');
        });
    }

    function flashInput($input, color) {
        $input.css('background-color', color);
        setTimeout(() => $input.css('background-color', ''), 900);
    }

    function recalcularTotalFila($tr) {
        if (modoEntrada !== 'numero' || !SHOW_TOTAL_COLUMN) return;
        let total = 0;
        $tr.find('.day-input').each(function() {
            const v = parseFloat($(this).val());
            if (!isNaN(v)) total += v;
        });
        $tr.find('.total-col').text(Math.round(total));
    }

    // ============================================================
    // CARGA DE VALORES YA GUARDADOS ESTE MES
    // ============================================================
    function cargarValoresExistentes(assets, startTs, endTs) {
        const key = modoEntrada === 'texto' ? KEY_TEXT : KEY_NUMERIC;
        let idx = 0;
        const BATCH_SIZE = 5;
        function next() {
            if (idx >= assets.length) return;
            const batch = assets.slice(idx, idx + BATCH_SIZE);
            idx += BATCH_SIZE;
            let completed = 0;
            batch.forEach(asset => {
                const url = '/api/plugins/telemetry/ASSET/' + asset.id.id + '/values/timeseries?keys=' + key + '&startTs=' + startTs + '&endTs=' + endTs + '&limit=100';
                $ctx.http.get(url).subscribe(function(data) {
                    pintarValores(asset.id.id, (data && data[key]) ? data[key] : []);
                    if (++completed === batch.length) next();
                }, function() { if (++completed === batch.length) next(); });
            });
        }
        next();
    }

    function pintarValores(assetId, items) {
        items.forEach(item => {
            const day = new Date(item.ts).getDate();
            const $input = $container.find('#input-' + assetId + '-' + day);
            if ($input.length) {
                $input.val(item.value);
                $input.data('valor-anterior', String(item.value));
            }
        });
        recalcularTotalFila($container.find('#row-' + assetId));
    }

    setTimeout(iniciar, 200);
};

